  { value: 'textiles', label: 'Textiles' },
  { value: 'woodwork', label: 'Woodwork' },
  { value: 'jewelry', label: 'Jewelry' },
];

export default function ProductsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const initialCategory = (searchParams.get('category') as Category) || 'all';

  const [activeCategory, setActiveCategory] = useState<Category>(initialCategory);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const cat = (searchParams.get('category') as Category) || 'all';
    setActiveCategory(cat);
  }, [searchParams]);

  useEffect(() => {
    setLoading(true);
    const url =
      activeCategory === 'all'
        ? '/api/products'
        : `/api/products?category=${activeCategory}`;

    fetch(url)
      .then((r) => r.json())
      .then((data: Product[]) => {
        setProducts(data);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [activeCategory]);

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    if (cat === 'all') {
      setSearchParams({});
    } else {
      setSearchParams({ category: cat });
    }
  };

  return (
    <>
      <Helmet>
        <title>Shop — Artisan Goods Co.</title>
        <meta
          name="description"
          content="Browse our full collection of handmade pottery, textiles, woodwork, and jewelry. Each piece crafted by skilled artisans."
