/**
 * Products service — client-side fetch helpers.
 *
 * All product data is served by /api/products (see src/server/api/products/GET.ts).
 * Components and route loaders should import from here rather than calling
 * fetch('/api/products') inline, so the URL and response shape are defined
 * in one place.
 */

import type { Product, ProductCategory } from './products-data';

// Re-export the shared types so consumers only need one import.
export type { Product, ProductCategory };

export interface GetProductsOptions {
  category?: ProductCategory;
  featured?: boolean;
}

/**
 * Fetch products from the API, optionally filtered by category or featured flag.
 * Throws on non-OK responses so callers / loaders can handle errors uniformly.
 */
export async function getProducts(options: GetProductsOptions = {}): Promise<Product[]> {
  const params = new URLSearchParams();
  if (options.category) params.set('category', options.category);
  if (options.featured) params.set('featured', 'true');

  const query = params.toString();
  const url = query ? `/api/products?${query}` : '/api/products';

  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Failed to fetch products: ${res.status} ${res.statusText}`);
  }
  return res.json() as Promise<Product[]>;
}

/**
 * Convenience helper — returns only featured products.
 */
export async function getFeaturedProducts(limit?: number): Promise<Product[]> {
  const products = await getProducts({ featured: true });
  return limit !== undefined ? products.slice(0, limit) : products;
}

import type { Request, Response } from 'express';
import { PRODUCTS } from '../../../lib/products-data.js';

export default function handler(req: Request, res: Response) {
  const { category, featured } = req.query;

  let result = [...PRODUCTS];

  if (category && typeof category === 'string') {
    const validCategories = ['pottery', 'textiles', 'woodwork', 'jewelry'];
    if (validCategories.includes(category)) {
      result = result.filter((p) => p.category === category);
    }
  }

  if (featured === 'true') {
    result = result.filter((p) => p.featured === true);
  }

  res.json(result);
}

